mapper.select:
SELECT CASE WHEN count(*) > 0 THEN 1 ELSE 0 END AS existence
FROM bt_env_variable
WHERE status_cd = '00A'
AND variable_code = #{dto.variableCode}
AND tenant_id = #{dto.tenantId}

  AND variable_id != #{dto.variableId}

mapper.update:
UPDATE bt_env_variable
SET variable_code = #{dto.variableCode},
variable_name = #{dto.variableName},
data_type = #{dto.dataType},
updator_id = #{dto.updatorId},
updated_time =,
remark = #{dto.remark}
WHERE variable_id = #{dto.variableId}
AND tenant_id = #{dto.tenantId}

UPDATE bt_env_variable_val
SET env_code = #{dto.envCode},
variable_val = #{dto.variableVal},
updator_id = #{dto.updatorId},
updated_time =,
remark = #{dto.remark}
WHERE variable_id = #{dto.variableId}
AND variable_val_id = #{dto.variableValId}
AND tenant_id = #{dto.tenantId}

