SELECT e.variable_id, e.data_type, v.variable_val
FROM bt_env_variable_val v
JOIN bt_env_variable e ON e.variable_id = v.variable_id
WHERE v.status_cd = '00A'
  AND e.status_cd = '00A'
  AND v.env_code = #{envCode}
  AND e.tenant_id = #{tenantId}
